/** Materialize a filter callback, shorthand, or AST without a database schema. */
export function buildFilter(input) {
    let ast;
    if (typeof input === 'function') {
        const node = input(new DefaultFilterBuilder());
        if (!isRecord(node) ||
            !['condition', 'group', 'relation'].includes(node.kind))
            inputError(['filter'], 'Callbacks must return a Filter node.');
        ast = {
            kind: 'filter',
            version: 1,
            root: node.kind === 'group'
                ? node
                : { kind: 'group', logic: 'and', items: [node] },
        };
    }
    else {
        if (!isRecord(input))
            inputError(['filter'], 'Expected a filter object.');
        if (input.kind === 'filter' &&
            input.version === 1)
            ast = input;
        else
            ast = {
                kind: 'filter',
                version: 1,
                root: {
                    kind: 'group',
                    logic: 'and',
                    items: Object.entries(input).map(([field, value]) => {
                        if (value !== null &&
                            !['string', 'number', 'boolean'].includes(typeof value))
                            inputError(['filter', field], 'Shorthand filters require scalar values.');
                        return {
                            kind: 'condition',
                            path: [field],
                            operator: '$eq',
                            value: value,
                        };
                    }),
                },
            };
    }
    return snapshotJson(ast);
}

